Here is the commit message:
nsfs: tighten permission checks for ns iteration ioctls

Even privileged services should not necessarily be able to see other
privileged service's namespaces so they can't leak information to each
other. Use may_see_all_namespaces() helper that centralizes this policy
until the nstree adapts.

Link: https://patch.msgid.link/20260226-work-visibility-fixes-v1-1-d2c2853313bd@kernel.org
Fixes: a1d220d9dafa ("nsfs: iterate through mount namespaces")
Reviewed-by: Jeff Layton <jlayton@kernel.org>
Cc: stable@kernel.org # v6.12+
Signed-off-by: Christian Brauner <brauner@kernel.org>

Here is the root cause:
The ioctl handler for NS_MNT_GET_NEXT and NS_MNT_GET_PREV in nsfs.c lacked sufficient permission checks, allowing any process with CAP_SYS_ADMIN to iterate through other namespaces, which could leak information between privileged services. The fix adds a check that restricts these ioctls to only processes in the initial PID namespace with CAP_SYS_ADMIN in the initial user namespace.

Here is the patch:

+static bool may_use_nsfs_ioctl(unsigned int cmd)
+{
+	switch (_IOC_NR(cmd)) {
+	case _IOC_NR(NS_MNT_GET_NEXT):
+		fallthrough;
+	case _IOC_NR(NS_MNT_GET_PREV):
+		return may_see_all_namespaces();
+	}
+	return true;
+}
+
 static long ns_ioctl(struct file *filp, unsigned int ioctl,
 			unsigned long arg)
 {
 	struct user_namespace *user_ns;
 	struct pid_namespace *pid_ns;
 	struct task_struct *tsk;
 	struct ns_common *ns;
 	struct mnt_namespace *mnt_ns;
 	bool previous = false;
 	uid_t __user *argp;
 	uid_t uid;
 	int ret;

 	if (!nsfs_ioctl_valid(ioctl))
 		return -ENOIOCTLCMD;
+	if (!may_use_nsfs_ioctl(ioctl))
+		return -EPERM;

 	ns = get_proc_ns(file_inode(filp));
 	switch (ioctl) {
 	case NS_GET_USERNS:
 		return open_related_ns(ns, ns_get_owner);
 	case NS_GET_PARENT:
 		if (!ns->ops->get_parent)
 			return -EINVAL;
 		return open_related_ns(ns, ns->ops->get_parent);
 	case NS_GET_NSTYPE:
 		return ns->ns_type;
 	case NS_GET_OWNER_UID:
 		if (ns->ns_type != CLONE_NEWUSER)
 			return -EINVAL;
 		user_ns = container_of(ns, struct user_namespace, ns);
 		argp = (uid_t __user *) arg;
 		uid = from_kuid_munged(current_user_ns(), user_ns->owner);
 		return put_user(uid, argp);
 	case NS_GET_PID_FROM_PIDNS:
 		fallthrough;
 	case NS_GET_TGID_FROM_PIDNS:
 		fallthrough;
 	case NS_GET_PID_IN_PIDNS:
 		fallthrough;
 	case NS_GET_TGID_IN_PIDNS: {
 		if (ns->ns_type != CLONE_NEWPID)
 			return -EINVAL;

 		ret = -ESRCH;
 		pid_ns = container_of(ns, struct pid_namespace, ns);

 		guard(rcu)();

 		if (ioctl == NS_GET_PID_IN_PIDNS ||
 		    ioctl == NS_GET_TGID_IN_PIDNS)
 			tsk = find_task_by_vpid(arg);
 		else
 			tsk = find_task_by_pid_ns(arg, pid_ns);
 		if (!tsk)
 			break;

 		switch (ioctl) {
 		case NS_GET_PID_FROM_PIDNS:
 			ret = task_pid_vnr(tsk);
 			break;
 		case NS_GET_TGID_FROM_PIDNS:
 			ret = task_tgid_vnr(tsk);
 			break;
 		case NS_GET_PID_IN_PIDNS:
 			ret = task_pid_nr_ns(tsk, pid_ns);
 			break;
 		case NS_GET_TGID_IN_PIDNS:
 			ret = task_tgid_nr_ns(tsk, pid_ns);
 			break;
 		default:
 			ret = 0;
 			break;
 		}

 		if (!ret)
 			ret = -ESRCH;
 		return ret;
 	}
 	case NS_GET_MNTNS_ID:
 		if (ns->ns_type != CLONE_NEWNS)
 			return -EINVAL;
 		fallthrough;
 	case NS_GET_ID: {
 		__u64 __user *idp;
 		__u64 id;

 		idp = (__u64 __user *)arg;
 		id = ns->ns_id;
 		return put_user(id, idp);
 	}
 	}

 	/* extensible ioctls */
 	switch (_IOC_NR(ioctl)) {
 	case _IOC_NR(NS_MNT_GET_INFO): {
 		struct mnt_ns_info kinfo = {};
 		struct mnt_ns_info __user *uinfo = (struct mnt_ns_info __user *)arg;
 		size_t usize = _IOC_SIZE(ioctl);

 		if (ns->ns_type != CLONE_NEWNS)
 			return -EINVAL;

 		if (!uinfo)
 			return -EINVAL;

 		if (usize < MNT_NS_INFO_SIZE_VER0)
 			return -EINVAL;

 		return copy_ns_info_to_user(to_mnt_ns(ns), uinfo, usize, &kinfo);
 	}
 	case _IOC_NR(NS_MNT_GET_PREV):
 		previous = true;
 		fallthrough;
 	case _IOC_NR(NS_MNT_GET_NEXT): {
 		struct mnt_ns_info kinfo = {};
 		struct mnt_ns_info __user *uinfo = (struct mnt_ns_info __user *)arg;
 		struct path path __free(path_put) = {};
 		size_t usize = _IOC_SIZE(ioctl);

 		if (ns->ns_type != CLONE_NEWNS)
 			return -EINVAL;

 		if (usize < MNT_NS_INFO_SIZE_VER0)
 			return -EINVAL;

 		mnt_ns = get_sequential_mnt_ns(to_mnt_ns(ns), previous);
 		if (IS_ERR(mnt_ns))
 			return PTR_ERR(mnt_ns);

 		ns = to_ns_common(mnt_ns);
 		/* Transfer ownership of @mnt_ns reference to @path. */
 		ret = path_from_stashed(&ns->stashed, nsfs_mnt, ns, &path);
 		if (ret)
 			return ret;

 		FD_PREPARE(fdf, O_CLOEXEC, dentry_open(&path, O_RDONLY, current_cred()));
 		if (fdf.err)
 			return fdf.err;
 		/*
 		 * If @uinfo is passed return all information about the
 		 * mount namespace as well.
 		 */
 		ret = copy_ns_info_to_user(to_mnt_ns(ns), uinfo, usize, &kinfo);
 		if (ret)
 			return ret;
 		ret = fd_publish(fdf);
 		break;
 	}
 	default:
 		ret = -ENOTTY;
 	}

 	return ret;
 }



